# Generated by Cursor
"""Quote-like character scan: classify open/close by space and apostrophe iff rules."""

import re

# Quote-like: U+0022, U+201C, U+201D, U+2018, U+2019, U+2033, U+2036, U+2035, U+2032, U+301D, U+00AB, U+00BB, U+0027
# Edited by Cursor: curly single quotes; U+2035 U+2032 U+301D U+2033 (prime-style)
QUOTE_LIKE_RE = re.compile(
    r'["\u201c\u201d\u2018\u2019\u2033\u2036\u2035\u2032\u301d\u00ab\u00bb\']+'
)
# Canonical open (left) / close (right) for ambiguous cases
CANONICAL_OPEN = frozenset("\u201c\u00ab\u2036\u2018\u2035\u301d")
CANONICAL_CLOSE = frozenset("\u201d\u00bb\u2033\u2019\u2032")
APOSTROPHE = "'"


def _word_at(text: str, pos: int) -> tuple[int, int]:
    """Return (start, end) of word containing pos (non-space run)."""
    if pos < 0 or pos >= len(text) or text[pos].isspace():
        return (pos, pos)
    start = pos
    while start > 0 and not text[start - 1].isspace():
        start -= 1
    end = pos + 1
    while end < len(text) and not text[end].isspace():
        end += 1
    return (start, end)


def _is_letter(c: str) -> bool:
    return len(c) == 1 and c.isalpha()


def scan_turn_quotes(
    text: str,
    path_str: str = "",
) -> list[tuple[str, int, str, str]]:
    """
    Scan text for quote-like runs; classify as open_double_quote or close_double_quote.

    Returns list of (rule_id, start_index, span, path_str).
    """
    result: list[tuple[str, int, str, str]] = []
    spans_list: list[tuple[int, str]] = []
    for m in QUOTE_LIKE_RE.finditer(text):
        spans_list.append((m.start(), m.group(0)))
    if not spans_list:
        return result

    n = len(text)
    # Tentative from space: space-before -> open, space-after -> close. Apostrophe always None so iff rules apply.
    tentative: list[tuple[int, str, str | None]] = []
    for start, span in spans_list:
        end = start + len(span)
        if span == APOSTROPHE:
            tentative.append((start, span, None))
            continue
        space_before = start == 0 or text[start - 1].isspace()
        space_after = end >= n or text[end].isspace()
        if space_before and not space_after:
            tentative.append((start, span, "open"))
        elif space_after and not space_before:
            tentative.append((start, span, "close"))
        else:
            tentative.append((start, span, None))

    # Apostrophe at start: open only if no unclosed open and unopened close directly after
    for i, (start, span, cls) in enumerate(tentative):
        if span != APOSTROPHE or cls is not None:
            continue
        end = start + len(span)
        word_start, word_end = _word_at(text, start)
        at_start_of_word = word_start == start and (end < n and _is_letter(text[end]))
        if not at_start_of_word:
            continue
        next_close_idx: int | None = None
        for j in range(i + 1, len(tentative)):
            if tentative[j][2] in ("close", None):
                next_close_idx = j
                break
        if next_close_idx is None:
            continue  # no close after -> do not set open
        unclosed_before = any(tentative[k][2] == "open" for k in range(i))
        if unclosed_before:
            continue
        no_other_between = all(
            tentative[k][2] is None for k in range(i + 1, next_close_idx)
        )
        if no_other_between:
            tentative[i] = (start, span, "open")

    # Apostrophe at end: close only if unclosed open and no unopened close directly after
    unclosed_open: int | None = None
    for i, (start, span, cls) in enumerate(tentative):
        if cls == "open":
            unclosed_open = i
        elif cls == "close":
            unclosed_open = None
        if span != APOSTROPHE or cls is not None:
            continue
        word_start, word_end = _word_at(text, start)
        at_end_of_word = (
            word_end == start + len(span) and start > 0 and _is_letter(text[start - 1])
        )
        if not at_end_of_word:
            continue
        next_idx = i + 1
        next_is_close = next_idx < len(tentative) and tentative[next_idx][2] == "close"
        if unclosed_open is not None and not next_is_close:
            tentative[i] = (start, span, "close")
            unclosed_open = None

    # Resolve remaining ambiguous: first non-apostrophe (so "next is close" is known), then apostrophe
    alternate_straight = False
    for i, (start, span, cls) in enumerate(tentative):
        if cls is not None or span == APOSTROPHE:
            continue
        c = span[0]
        end = start + len(span)
        if c in CANONICAL_OPEN:
            tentative[i] = (start, span, "open")
        elif c in CANONICAL_CLOSE:
            tentative[i] = (start, span, "close")
        else:
            # Straight " (U+0022)
            space_before = start == 0 or text[start - 1].isspace()
            space_after = end >= n or text[end].isspace()
            if space_before and space_after:
                at_end = end >= n
                at_start = start == 0
                if at_end and not at_start:
                    tentative[i] = (start, span, "close")
                elif at_start and not at_end:
                    tentative[i] = (start, span, "open")
                else:
                    tentative[i] = (
                        start,
                        span,
                        "close" if alternate_straight else "open",
                    )
                    alternate_straight = True
            else:
                tentative[i] = (
                    start,
                    span,
                    "close" if (end >= n or text[end].isspace()) else "open",
                )
    for i, (start, span, cls) in enumerate(tentative):
        if cls is not None or span != APOSTROPHE:
            continue
        end = start + len(span)
        word_start, word_end = _word_at(text, start)
        at_end_of_word = word_end == end and start > 0 and _is_letter(text[start - 1])
        next_is_close = i + 1 < len(tentative) and tentative[i + 1][2] == "close"
        if at_end_of_word and next_is_close:
            continue  # leave None -> do not emit
        tentative[i] = (start, span, "close")

    for start, span, cls in tentative:
        if cls not in ("open", "close"):
            continue
        rule_id = "open_double_quote" if cls == "open" else "close_double_quote"
        result.append((rule_id, start, span, path_str))
    return result
